const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const net = require('node:net');
const http = require('node:http');
const { once } = require('node:events');
require('./test/test-env').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pd-r6-'));
process.env.HOME = home;
process.env.PORT = '0';
process.env.TMUX_TMPDIR = path.join(home, 'tmux');
fs.mkdirSync(process.env.TMUX_TMPDIR);
process.env.PI_DISH_PI_COMMAND = `${process.execPath} ${path.resolve('test/fixtures/fake-rpc-pi.js')}`;
const id = 'r6-replay-smoke';
const cwd = path.join(home, 'workspace');
const sessions = path.join(home, '.pi', 'agent', 'sessions', 'smoke');
const registry = path.join(home, '.pi', 'dish', 'sessions');
for (const dir of [cwd, sessions, registry]) fs.mkdirSync(dir, { recursive: true });
const sessionFile = path.join(sessions, id + '.jsonl');
fs.writeFileSync(sessionFile, [
  { type: 'session', id, cwd, timestamp: new Date().toISOString() },
  { type: 'message', id: 'hello', message: { role: 'assistant', content: [{ type: 'text', text: 'R6 isolated replay fixture.' }], timestamp: Date.now() } },
].map(value => JSON.stringify(value)).join('\n') + '\n');
const socketPath = path.join(home, 'bridge.sock');
const clients = new Set();
const responses = [];
let connections = 0;
let replay = [];
const send = (sock, value) => sock.write(JSON.stringify(value) + '\n');
const emit = (event, data) => { for (const sock of clients) send(sock, { type: 'event', event, data }); };
const bridge = net.createServer(sock => {
  connections++;
  clients.add(sock);
  sock.on('close', () => clients.delete(sock));
  sock.on('error', () => {});
  send(sock, { type: 'hello', turnInProgress: true, queue: { steering: [], followUp: [] } });
  for (const data of replay) send(sock, { type: 'event', event: 'extension_ui_request', data });
  let buffer = '';
  sock.on('data', chunk => {
    buffer += chunk;
    let end;
    while ((end = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0, end); buffer = buffer.slice(end + 1);
      if (!line) continue;
      const command = JSON.parse(line);
      let data = {};
      if (command.command === 'get_available_models') data = { models: [{ provider: 'test', id: 'r6', name: 'R6 smoke', contextWindow: 200000 }] };
      if (command.command === 'get_commands') data = [];
      if (command.command === 'tree_leaf') data = { leafId: 'hello' };
      if (command.command === 'get_state') data = { sessionId: id, sessionFile, cwd, turnInProgress: true };
      if (command.command === 'extension_ui_response') responses.push(command);
      send(sock, { type: 'response', id: command.id, success: true, data });
    }
  });
});
(async () => {
  bridge.listen(socketPath); await once(bridge, 'listening');
  fs.writeFileSync(path.join(registry, id + '.json'), JSON.stringify({ sessionId: id, socketPath, sessionFile, cwd, pid: process.pid, name: 'R6 replay smoke', turnInProgress: true, model: 'test/r6' }));
  const server = require('./server');
  if (!server.listening) await once(server, 'listening');
  const control = http.createServer(async (req, res) => {
    if (req.method === 'POST') {
      let raw = ''; for await (const chunk of req) raw += chunk;
      const body = raw ? JSON.parse(raw) : {};
      if (req.url === '/emit') emit(body.event, body.data);
      if (req.url === '/reconnect') { replay = body.replay || []; for (const sock of clients) sock.destroy(); }
    }
    res.setHeader('Content-Type', 'application/json');
    res.end(JSON.stringify({ connections, clients: clients.size, responses, home, sessionId: id }));
  });
  control.listen(0, '127.0.0.1'); await once(control, 'listening');
  console.log('R6_READY ' + JSON.stringify({ base: `http://127.0.0.1:${server.address().port}`, control: `http://127.0.0.1:${control.address().port}`, id, home }));
  let stopping = false;
  const stop = () => {
    if (stopping) return; stopping = true;
    for (const sock of clients) sock.destroy();
    control.close(); bridge.close(); server.close();
    fs.rmSync(home, { recursive: true, force: true });
  };
  process.on('SIGTERM', stop);
  process.on('SIGINT', stop);
})().catch(error => { console.error(error); process.exitCode = 1; });

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { spawn } = require('node:child_process');
const { once } = require('node:events');
const { sanitizeTestEnv } = require('./test/test-env');
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pd-r6-native-'));
const env = sanitizeTestEnv({ PATH: process.env.PATH, HOME: home, TMUX: '', TMUX_PANE: '' });
env.PI_DISH_SOCKET_DIR = path.join(home, 's');
const agentDir = path.join(home, '.pi', 'agent');
const extensions = path.join(agentDir, 'extensions');
fs.mkdirSync(extensions, { recursive: true });
fs.symlinkSync(path.resolve('extensions/pi-dish-bridge'), path.join(extensions, 'pi-dish-bridge'));
fs.writeFileSync(path.join(agentDir, 'models.json'), JSON.stringify({ providers: { isolated: { baseUrl: 'http://127.0.0.1:1', apiKey: 'not-a-credential', api: 'anthropic-messages', models: [{ id: 'no-provider-call', name: 'Isolated', contextWindow: 200000, maxTokens: 8192 }] } } }));
fs.writeFileSync(path.join(extensions, 'r6-dialog.ts'), `export default function(pi) { pi.registerCommand('r6-ui', { description: 'Isolated R6 proof', handler: async (_args, ctx) => { ctx.ui.setWidget('r6-native', ['native socket replay']); ctx.ui.setStatus('r6-native', 'native status'); const answer = await ctx.ui.input('R6 native pending input'); ctx.ui.setStatus('r6-answer', answer || 'cancelled'); } }); }`);
const child = spawn('/home/jyarwood/.local/bin/pi', ['--mode', 'rpc', '--model', 'isolated/no-provider-call'], { cwd: home, env, stdio: ['pipe', 'pipe', 'pipe'] });
let stderr = '';
child.stderr.on('data', chunk => { stderr += chunk; });
child.stdout.resume();
const waitFor = async (predicate, label) => {
  const deadline = Date.now() + 30000;
  while (Date.now() < deadline) {
    const value = predicate(); if (value) return value;
    if (child.exitCode !== null) throw new Error('Pi exited: ' + stderr);
    await new Promise(resolve => setTimeout(resolve, 25));
  }
  throw new Error('Timeout: ' + label + '\n' + stderr);
};
let first, second;
(async () => {
  const claim = await waitFor(() => {
    try {
      const dir = path.join(home, '.pi', 'dish', 'sessions');
      const file = fs.readdirSync(dir).find(name => name.endsWith('.json'));
      return file && JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    } catch { return null; }
  }, 'native registration');
  const { BridgeSession } = require('./lib/bridge-session');
  first = await new BridgeSession(claim).connect();
  child.stdin.write(JSON.stringify({ type: 'prompt', id: 'r6-command', message: '/r6-ui' }) + '\n');
  await waitFor(() => first.extUIState.dialogs.size === 1, 'first native dialog');
  assert.deepEqual(first.extUIState.widgets.get('r6-native').widgetLines, ['native socket replay']);
  const dialog = [...first.extUIState.dialogs.values()][0];
  assert.equal(dialog.title, 'R6 native pending input');
  first.close();
  second = await new BridgeSession(claim).connect();
  await waitFor(() => second.extUIState.dialogs.has(dialog.id), 'harness replay into new server socket');
  assert.deepEqual(second.extUIState.widgets.get('r6-native').widgetLines, ['native socket replay']);
  assert.equal(second.extUIState.statuses.get('r6-native').statusText, 'native status');
  await second.respondExtensionUI(dialog.id, { value: 'native-answer' });
  await waitFor(() => second.extUIState.dialogs.size === 0 && second.extUIState.statuses.get('r6-answer')?.statusText === 'native-answer', 'native answer resolution');
  console.log(JSON.stringify({ result: 'PASS', harness: 'real Pi', source: process.cwd(), proof: ['native loader and private capture', 'native UI request before server reconnect', 'separate server socket native harness replay', 'pending input preserved across socket replacement', 'remote answer resolves native dialog and status'], providerRequests: 0, sessionId: claim.sessionId }));
})().catch(error => { console.error(error); process.exitCode = 1; }).finally(async () => {
  first?.close(); second?.close();
  if (child.exitCode === null) { const exited = once(child, 'exit'); child.kill('SIGTERM'); await exited; }
  fs.rmSync(home, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
});
